local IconAliases = {
    ["circle-check"] = "check-circle",
    ["circle-x"] = "x-circle",
    ["triangle-alert"] = "alert-triangle",
    ["key-round"] = "key",
    ["house"] = "home",
    ["gear"] = "settings",
    ["close"] = "x",
}

local function GetIcon(name)
    if name == nil or name == "" then
        return nil
    end
    if type(name) == "number" then
        return "rbxassetid://" .. name
    end
    name = tostring(name)
    if string.find(name, "rbxasset", 1, true) then
        return name
    end
    local key = (string.gsub(string.lower(name), "^lucide%-", ""))
    local id = IconIds[key] or IconIds[IconAliases[key] or ""]
    return id and ("rbxassetid://" .. id) or nil
end

function SlimeUI:GetIcon(name)
    return GetIcon(name)
end

